  uint32_t lx;
  EXTRACT_WORDS(hx, lx, x);
  hx &= 0x7fffffff;  /* |x| */
  return (hx >= 0x7ff00000) && ((hx - 0x7ff00000) | lx) != 0;  /* 3.7.4 patch */
