      if (ix >= 0x3FFBB4C3) { y = 2.0 - x; i = 0; } /* [1.7316,2] */
      else if (ix >= 0x3FF3B4C4) {y = x - tc; i = 1; } /* [1.23,1.73] */
      else { y = x - one; i = 2; }
