  n = (n + 1)/2;
  x -= n*0.5f;
  x *= lpi;
  switch (n) {
    default: /* case 4: */
    case 0: return sun_sinl(x);
    case 1: return sun_cosl(x);
    case 2: return sun_sinl(-x);
    case 3: return -sun_cosl(x);
  }
