/**
 * Generated by Gemini AI, put into the public domain. 30/10/2025
 * @brief Deterministic Miller-Rabin Primality Test for all numbers < 2^64.
 * This function replaces the slow trial division loop for large numbers.
 * @param x The 64-bit number to test for primality.
 * @return 1 if x is prime, 0 if x is composite.
 * Algorithm: Deterministic Miller-Rabin Primality Test.
 * Purpose: To achieve primality testing speed for 64-bit integers, replacing the trial division method.
 * Key Detail: The deterministic nature for all uint64_t inputs relies on testing against the specific set of 7 bases.
 * Crucial Helper: The use of safe modular multiplication (tools_mulmodu64), which avoids intermediate 64-bit overflow,
 * is necessary for correctness when working with moduli near UINT64_MAX. 6.3.4
 */
static int check_base (uint64_t x, uint64_t a, uint64_t d, int s) {
  int r;
  /* 1. Compute a^d mod x */
  uint64_t current = tools_powmodu64(a, d, x);
  /* 2. Check the first condition: a^d = 1 mod x */
  if (current == 1) return 1;
  /* 3. Check the second condition: a^(2^r * d) = -1 mod x for 0 <= r < s */
  for (r=0; r < s; r++) {
    /* Equivalent to checking a^(2^r * d) = x - 1 mod x */
    if (current == x - 1) return 1;
    /* Square the result for the next iteration: a^(2^(r+1) * d) mod x */
    current = tools_mulmodu64(current, current, x);
  }
  /* If neither condition is met, x is composite. */
  return 0;
}

static int miller_rabin_isprime (uint64_t x) {
  /* Handle small edge cases (optional, but good practice) */
  int i, s;
  uint64_t a, d;
  if (x <= 1) return 0;
  if (x == 2 || x == 3) return 1;
  if (x % 2 == 0) return 0;
  /* 1. Decompose x - 1 into 2^s * d, where d is odd */
  d = x - 1;
  s = 0;
  while ((d & 1) == 0) {
    d >>= 1;
    s++;
  }
  /* The set of 7 bases required for deterministic test up to 2^64 */
  const uint64_t bases[] = {2, 325, 9375, 28178, 450775, 9780504, 1795265022};
  const int num_bases = sizeof(bases)/sizeof(bases[0]);
  /* 2. Run the test for all 7 bases */
  for (i=0; i < num_bases; i++) {
    a = bases[i];
    /* Skip bases that are >= x */
    if (a >= x) break;  /* Since bases are sorted and ascending, we can break */
    /* If 'check_base' fails for any 'a', x is definitely composite. */
    if (!check_base(x, a, d, s)) return 0;
  }
  /* If all checks pass, x is deterministically prime. */
  return 1;
}


